#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

vector<ll> subsetSums(const vector<ll> &v) {
    int m = v.size();
    vector<ll> s(1 << m, 0);                  // s[mask] = mask 에 든 원소들의 합
    for (int mask = 1; mask < (1 << m); mask++) {
        int low = __builtin_ctz(mask);        // 가장 낮은 켜진 비트
        s[mask] = s[mask & (mask - 1)] + v[low];
    }
    return s;
}

int main() {
    int n;
    ll S;
    cin >> n >> S;
    vector<ll> a(n);
    for (auto &x : a) cin >> x;
    vector<ll> L = subsetSums(vector<ll>(a.begin(), a.begin() + n / 2));
    vector<ll> R = subsetSums(vector<ll>(a.begin() + n / 2, a.end()));
    sort(R.begin(), R.end());
    cout << "반쪽 크기 " << L.size() << ' ' << R.size() << '\n';

    ll le = 0, eq = 0;                        // 개수는 2^N 까지 커지니 long long
    for (ll s : L) {
        le += upper_bound(R.begin(), R.end(), S - s) - R.begin();
        auto [lo, hi] = equal_range(R.begin(), R.end(), S - s);
        eq += hi - lo;
    }
    cout << "S 이하 " << le << '\n';
    cout << "정확히 S " << eq << '\n';
    cout << "공집합 제외 S 이하 " << le - (S >= 0 ? 1 : 0) << '\n';

    // 투 포인터: L 오름차순, R 내림차순으로 보며 S 이하인 가장 큰 합
    sort(L.begin(), L.end());
    ll best = LLONG_MIN;
    int j = (int)R.size() - 1;
    for (ll s : L) {
        while (j >= 0 && s + R[j] > S) j--;
        if (j < 0) break;
        best = max(best, s + R[j]);
    }
    cout << "S 이하 최대 합 " << best << '\n';
    return 0;
}

